-- ============================================================================
-- div_signals sync — KJT-LNL and KSRA-IGP are missing on production
-- 2026-07-13
--
-- WHY
-- Prod holds 1345 signals, local 1503. The gap is not scattered: every other
-- section matches count-for-count, and prod is missing TWO WHOLE SECTIONS —
--   KJT-LNL   98 signals   (Karjat - Lonavla ghat)
--   KSRA-IGP  60 signals   (Kasara - Igatpuri ghat)
-- 158 signals, exactly the difference. They were imported locally after prod
-- was last seeded.
--
-- WHY IT MATTERS FOR AWS, AND WHY IT MUST BE RUN BEFORE THE RELOAD
-- Signal matching happens AT UPLOAD. A signal that is not in div_signals cannot
-- be matched, and the only way to fix it afterwards is to delete the events and
-- re-parse — i.e. to do the whole truncate-and-reload again.
--
-- Worse than a missing match: a WRONG one. KJT signals exist in BOTH KJT-LNL and
-- KJT-KHPI. Prod has KJT-KHPI but not KJT-LNL, so an EMU act at "KJT S-22" (a
-- real event: KYNS/06-06-2026/ST/1) would confidently match the KJT-KHPI copy —
-- the wrong magnet, on the wrong section, counted against the wrong S&T beat.
-- That mis-match is silent: the event looks perfectly resolved.
--
-- SAFETY
--   * Signal ids 2010-2167 are used below. Prod's MAX(id) is 2009, so there is
--     no collision and the ids can be preserved — which matters, because the
--     aliases point at them by id.
--   * Aliases are inserted WITHOUT ids (their local ids overlap prod's range)
--     and with INSERT IGNORE, deduplicated by the UNIQUE key on
--     normalized_alias. Re-running this file is therefore harmless.
--   * Nothing is deleted or updated. This file only ADDS.
--
-- RUN IT BEFORE reloading the AWS files:
--   scp sql/2026-07-13_signals_sync_kjt_lnl_ksra_igp.sql railway@93.127.198.125:~/
--   mysql -u <user> -p bbtro < 2026-07-13_signals_sync_kjt_lnl_ksra_igp.sql
-- ============================================================================

SELECT '--- before ---' AS ``;
SELECT COUNT(*) AS signals_before, MAX(id) AS max_id_before FROM div_signals;
SELECT COUNT(*) AS aliases_before FROM div_signal_aliases;

-- ── Signals: KJT-LNL (98) + KSRA-IGP (60) ──────────────────────────────────

-- ── Aliases for those signals (ids NOT preserved; deduped on normalized_alias) ──

SELECT '--- after (expect signals 1345 -> 1503) ---' AS ``;
SELECT COUNT(*) AS signals_after, MAX(id) AS max_id_after FROM div_signals;
SELECT COUNT(*) AS aliases_after FROM div_signal_aliases;

SELECT section, COUNT(*) AS n FROM div_signals
 WHERE section IN ('KJT-LNL','KSRA-IGP') GROUP BY section;

-- The mis-match this prevents: both copies must now exist.
SELECT id, signal_number, section, direction FROM div_signals
 WHERE normalized_signal_number IN ('KJTS22','KJTS106') ORDER BY signal_number, section;
